input.command:
cd /work; psql -q -v ON_ERROR_STOP=1 <<'EOF'
DELETE FROM order_items WHERE order_id IN (9000001,9000002);
DELETE FROM orders WHERE order_id IN (9000001,9000002);
EOF
psql -tc "select count(*) from orders where order_id>9000000"
# multi-category test: pick two products of different categories; first line = higher product_id category
psql -q -v ON_ERROR_STOP=1 <<'EOF'
INSERT INTO orders SELECT 9000002,customer_id,'2030-01-15','COMPLETED',0 FROM customers LIMIT 1;
INSERT INTO order_items SELECT 9100001,9000002,(select max(product_id) from products where category=(select min(category) from products)),2,5;
INSERT INTO order_items SELECT 9100002,9000002,(select max(product_id) from products where category=(select max(category) from products)),7,9;
EOF
psql -q -v ON_ERROR_STOP=1 -f etl.sql
psql <<'EOF'
SELECT oi.order_item_id,p.category,oi.quantity,oi.unit_price FROM order_items oi JOIN products p USING(product_id) WHERE order_id=9000002;
SELECT * FROM dash_revenue_by_category WHERE month='2030-01';
SELECT source_order_count,loaded_order_count,mismatch FROM etl_run_log ORDER BY run_id DESC LIMIT 1;
EOF
# cleanup and rerun
psql -q -c "DELETE FROM order_items WHERE order_id=9000002; DELETE FROM orders WHERE order_id=9000002;"
psql -q -v ON_ERROR_STOP=1 -f etl.sql
psql -tc "select count(*) from orders where order_id>9000000; select source_order_count,loaded_order_count,mismatch from etl_run_log order by run_id desc limit 1"

